"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["5466"],{4621(e){e.exports=JSON.parse('{"id":"F345","slug":"black-76-option","name":"Black-76: Caplet or Swaption Price","subject":"Derivatives","section":"Derivatives","topic":"Swaptions, caps and floors","level":"Intermediate","aliases":["Black model","payer swaption","receiver swaption","caplet pricing","forward rate option"],"formula":{"latex":"\\\\text{Payer}=N\\\\,A\\\\,[F\\\\,N(d_{1})-K\\\\,N(d_{2})],\\\\ \\\\text{Receiver}=N\\\\,A\\\\,[K\\\\,N(-d_{2})-F\\\\,N(-d_{1})],\\\\ d_{1}=\\\\frac{\\\\ln(F/K)+\\\\sigma^{2}T/2}{\\\\sigma\\\\sqrt{T}}","also":[],"text":"Payer option (caplet, or payer swaption) = Notional x Annuity x [F x N(d1) - K x N(d2)]; Receiver option = Notional x Annuity x [K x N(-d2) - F x N(-d1)]; d1 = [ln(F/K) + sigma^2 x T / 2] / (sigma x sqrt(T)); d2 = d1 - sigma x sqrt(T)"},"symbols":[{"symbol":"F","meaning":"Forward rate (for a caplet) or forward swap rate (for a swaption)","unit":"per year"},{"symbol":"K","meaning":"Strike rate","unit":"per year"},{"symbol":"sigma","meaning":"Volatility of the forward rate","unit":"per year"},{"symbol":"T","meaning":"Time until the option expires","unit":"years"},{"symbol":"A","meaning":"Annuity factor: for a caplet, accrual fraction x discount factor to the payment date; for a swaption, the sum of those over the swap payment dates","unit":"number"},{"symbol":"N","meaning":"Notional","unit":"money"}],"when_to_use":"Use it to price options on interest rates, which are quoted market-standard with Black\'s model: caplets, floorlets and swaptions. It treats the forward rate as lognormal, and the annuity converts the result into present-value money.","worked_example":{"problem":"A 1-year option on a rate has a forward of 4.5%, a strike of 4.0%, a volatility of 25% and a notional of 10,000,000. The annuity factor is 1.85 (a 2-year swap with discount factors summing to 1.85 on annual payments). What are the payer and receiver prices?","inputs":{"f":4.5,"k":4,"sig":25,"t":1,"a":1.85,"n":10000000},"steps":[{"label":"d1 = [ln(F/K) + sigma^2 T / 2] / (sigma sqrt(T))","working":"(ln(0.045 / 0.04)+0.25^2 x 1 / 2) / (0.25 x sqrt(1))","value":"0.5961"},{"label":"d2 = d1 - sigma sqrt(T)","working":"d1-0.25 x sqrt(1)","value":"0.3461"},{"label":"Payer = N x A x [F N(d1) - K N(d2)]","working":null,"value":"132,930.12"},{"label":"Receiver = N x A x [K N(-d2) - F N(-d1)]","working":null,"value":"40,430.12"}],"answer":"With d1 = 0.5961 and d2 = 0.3461, the payer option (caplet or payer swaption) costs 132,930.12 and the receiver option costs 40,430.12. The payer is worth more because the forward is above the strike."},"calculator":{"available":true,"inputs":[{"id":"f","label":"Forward rate","unit":"%","type":"number","default":4.5,"hint":""},{"id":"k","label":"Strike rate","unit":"%","type":"number","default":4,"hint":""},{"id":"sig","label":"Volatility","unit":"%","type":"number","default":25,"hint":""},{"id":"t","label":"Time to expiry","unit":"years","type":"number","default":1,"hint":"","min":0.01},{"id":"a","label":"Annuity factor","unit":"","type":"number","default":1.85,"hint":""},{"id":"n","label":"Notional","unit":"money","type":"number","default":10000000,"hint":""}],"checks":[{"expr":"f>0 and k>0 and sig>0","message":"The forward, strike and volatility must be above zero."}],"steps":[{"id":"d1","label":"d1 = [ln(F/K) + sigma^2 T / 2] / (sigma sqrt(T))","expr":"(ln(f/k)+sig^2*t/2)/(sig*sqrt(t))","format":"num4"},{"id":"d2","label":"d2 = d1 - sigma sqrt(T)","expr":"d1-sig*sqrt(t)","format":"num4"},{"id":"payer","label":"Payer = N x A x [F N(d1) - K N(d2)]","expr":"n*a*(f*normcdf(d1)-k*normcdf(d2))","format":"money"},{"id":"receiver","label":"Receiver = N x A x [K N(-d2) - F N(-d1)]","expr":"n*a*(k*normcdf(-d2)-f*normcdf(-d1))","format":"money"}],"results":["payer","receiver"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"payer":132930.11693819202,"receiver":40430.11693819199}},"finder":{"finds":"The price of a caplet, floorlet or swaption","needs":"Forward rate, strike, volatility, time, annuity, notional"},"related":[{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price"},{"slug":"cap-floor-payoffs","name":"Interest Rate Cap and Floor Payoffs"},{"slug":"swap-fixed-rate","name":"Interest Rate Swap: Fair Fixed Rate"}],"related_ids":["F331","F346","F340"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Payer</mtext><mo>=</mo><mi>N</mi><mtext>\u2009</mtext><mi>A</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">[</mo><mi>F</mi><mtext>\u2009</mtext><mi>N</mi><mo stretchy=\\"false\\">(</mo><msub><mi>d</mi><mn>1</mn></msub><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mi>K</mi><mtext>\u2009</mtext><mi>N</mi><mo stretchy=\\"false\\">(</mo><msub><mi>d</mi><mn>2</mn></msub><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">]</mo><mo separator=\\"true\\">,</mo><mtext>\xa0Receiver</mtext><mo>=</mo><mi>N</mi><mtext>\u2009</mtext><mi>A</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">[</mo><mi>K</mi><mtext>\u2009</mtext><mi>N</mi><mo stretchy=\\"false\\">(</mo><mo>\u2212</mo><msub><mi>d</mi><mn>2</mn></msub><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mi>F</mi><mtext>\u2009</mtext><mi>N</mi><mo stretchy=\\"false\\">(</mo><mo>\u2212</mo><msub><mi>d</mi><mn>1</mn></msub><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">]</mo><mo separator=\\"true\\">,</mo><mtext>\xa0</mtext><msub><mi>d</mi><mn>1</mn></msub><mo>=</mo><mfrac><mrow><mi>ln</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mi>F</mi><mi mathvariant=\\"normal\\">/</mi><mi>K</mi><mo stretchy=\\"false\\">)</mo><mo>+</mo><msup><mi>\u03C3</mi><mn>2</mn></msup><mi>T</mi><mi mathvariant=\\"normal\\">/</mi><mn>2</mn></mrow><mrow><mi>\u03C3</mi><msqrt><mi>T</mi></msqrt></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Payer}=N\\\\,A\\\\,[F\\\\,N(d_{1})-K\\\\,N(d_{2})],\\\\ \\\\text{Receiver}=N\\\\,A\\\\,[K\\\\,N(-d_{2})-F\\\\,N(-d_{1})],\\\\ d_{1}=\\\\frac{\\\\ln(F/K)+\\\\sigma^{2}T/2}{\\\\sigma\\\\sqrt{T}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"bitcoin-supply-schedule","name":"Bitcoin Supply Schedule and Issuance Rate"},"next":{"slug":"black-litterman-one-asset","name":"Black-Litterman: Blending a View with Equilibrium (One Asset)"},"lesson":null,"total":522}')}}]);